import pathlib,json
root=pathlib.Path('/opt/febro-ecosystem');work=root/'phase4';info={
'central':('Febro Space','SQLite email/password/Google, sesi native dan issuer legacy.','Provider OIDC terpelihara, mount /profile, key persisten, fresh reauthentication, nonce Google, rotasi refresh, logout, rate limit dan audit.','Dependency pusat masih 1 high + 2 moderate; HTTPS staging dan credential/registrasi nyata belum diterima.'),
'lamariva':('Lamariva','better-auth email/password/Google; pemulihan password dan role native.','Rute /auth/febro, sesi signed-cookie better-auth native, pengaitan eksplisit; implicit Google email linking ditolak; sanitize-html dipatch kompatibel.','Provider pusat belum aktif; HTTPS/Google staging dan callback logging belum diterima.'),
'itinerary':('Itinerary','Legacy OIDC dan pengaitan password; login password sebelumnya dinonaktifkan.','Login password dipulihkan dengan CSRF/rate limit; rute baru /auth/space; callback legacy tetap; sesi Express diregenerasi; role native dipertahankan.','Provider/HTTPS staging belum diterima; aktivasi ls-itinerary.service memerlukan operator systemd berwenang.'),
'voltlab':('VoltLab','Google dan password administrator; sesi hashed PostgreSQL.','Rute /api/auth/febro, sesi native, fresh proof, UI login/profil; Google email collision ditolak; Next.js dinaikkan ke 16.4.2.','Provider/HTTPS dan Google staging belum diterima; kebijakan callback logging perlu perubahan terpisah yang disetujui.'),
'files':('Files','OIDC issuer legacy; sesi SQLite dan ownership accounts.sub.','Rute /auth/febro menggunakan discovery/PKCE/verifikasi pustaka, mapping terpisah ke sub asli, bukti sesi Files baru, konfirmasi dan regenerasi sesi.','Hanya kandidat terisolasi; dual ownership dan isolasi telah diuji sintetis, tetapi HTTPS staging dan persetujuan rollout masih wajib.'),
'play':('Play','Guest fa_player dan leaderboard anonim; score anti-abuse native.','Login opsional, claim Guest eksplisit, sesi autentikasi terpisah delapan jam; endpoint skor memilih pemain di server; logout kembali ke Guest tanpa mengubah runs/bests.','Provider/HTTPS staging belum diterima; registrasi/logout callback dan callback logging belum diotorisasi.')}
text='# Status aplikasi Phase 4\n\nSeluruh perubahan berikut hanya ada pada kandidat staging. Tidak satu pun integrasi baru diaktifkan di produksi.\n\n| Aplikasi | Implementasi staging | Kesiapan aktivasi produksi |\n|---|---|---|\n'
for app,(name,*_) in info.items():text+=f'| {name} | Kode nyata tersedia; pengujian terkait lulus | **BELUM SIAP**; gate pada uraian di bawah |\n'
summary={}
for app,(name,old,change,block) in info.items():
 m=json.loads((work/'releases'/app/'manifest.json').read_text());native=[p for p in m['files'] if not p.startswith('sso/')];shared=[p for p in m['files'] if p.startswith('sso/')];summary[app]={'artifact_sha256':m['artifact_sha256'],'modifiedNativeFiles':native,'sharedRuntimeFiles':shared,'productionReady':False}
 text+=f'\n## {name}\n\nAutentikasi awal: {old}\n\nPerubahan: {change}\n\nBerkas native berubah/baru:\n\n'+''.join('- `'+p+'`\n' for p in native)+f'\nDitambah `{len(shared)}` berkas runtime server-only `sso/`; daftar lengkap dan checksum berada pada `phase4/releases/{app}/manifest.json`. Tidak ada .env, database, upload atau signing secret dalam artefak.\n\n'
 if app=='central':text+='Pengujian: discovery/path issuer, PKCE S256, nonce/state, redirect, fresh login, consent/CSRF, code replay, refresh rotation/reuse, revocation, persistent keys dan restart provider. Login/password/authorization lama lulus regresi. Google nyata dan penerimaan publik stack baru belum diuji.\n\n'
 else:text+='Pengujian: login lokal sintetis/native, OIDC code/PKCE nyata terhadap OP fixture, konfirmasi pengaitan, pemilihan ID asli, isolasi kepemilikan, login/logout browser mobile 390px dan desktop 1366px. Rincian restart/expiry ada di laporan pengujian akhir.\n\n'
 text+='Blocker: '+block+'\n\n'
 text+=f'Perintah pemeriksaan aman: `python3 phase4/scripts/release.py verify {app}`. Dry-run migrasi: '+('provider memakai state database terpisah dan tidak memigrasikan users pusat.' if app=='central' else f'`node phase4/scripts/migrate.mjs {app} --dry-run`.')+'\n\n'
 if app=='itinerary':text+='Deployment/rollback: ikuti manifest, npm ci dan npm run check di jendela yang disetujui; operator systemd menangani unit ls-itinerary.service. Runner produksi menolak aplikasi ini agar tidak mencoba operasi elevated atau menciptakan proses PM2 baru.\n'
 else:text+=f'Deployment setelah approval dan acceptance: `python3 phase4/scripts/release.py deploy {app} /absolute/path/to/reviewed-{app}-approval.json`. Rollback memerlukan approval terpisah operation=rollback: `python3 phase4/scripts/release.py rollback {app} /absolute/path/to/reviewed-{app}-rollback-approval.json`. Perintah aktivasi ini belum dijalankan.\n'
 text+='\nRollback hanya berkas yang tercatat; mapping, user ID, role, credential lama dan seluruh konten/skor pengguna tidak direvert. Lihat SSO_PHASE4_DEPLOYMENT.md untuk prasyarat dan pemulihan jika build/dependency gagal.\n'
(root/'SSO_PHASE4_APPLICATION_STATUS.md').write_text(text);(work/'evidence/application-artifacts.json').write_text(json.dumps(summary,indent=2)+'\n')
